#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

static void init_gpioc(void);
static void EXTI13_init(void);



volatile uint32_t exti13_flag = 0;
volatile uint32_t interrupt_count = 0;



int main(void)
{
    init_gpioc();
    EXTI13_init();

    /* Loop forever */
	while (1)
    {
        if (exti13_flag)
        {
            exti13_flag = 0;
            interrupt_count++;
        }
    }
    return 0;
}


static void init_gpioc(void)
{
    /* Enable GPIOC clock */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

    /* Set PC13 as input */
    GPIOC->MODER &= ~(GPIO_MODER_MODE13_Msk);

    /* Set PC13 as no pull-up, no pull-down */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD13_Msk);
}

static void EXTI13_init(void)
{
    /* Enable SYSCFG clock */
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;

    /* Connect EXTI line 13 to PC13 */
    SYSCFG->EXTICR[3] &= ~(SYSCFG_EXTICR4_EXTI13_Msk);
    SYSCFG->EXTICR[3] |= (SYSCFG_EXTICR4_EXTI13_PC);

    /* Configure EXTI line 13 for falling edge trigger */
    EXTI->FTSR |= EXTI_FTSR_TR13;
    EXTI->RTSR &= ~(EXTI_RTSR_TR13);

    /* Enable EXTI line 13 interrupt */
    EXTI->IMR |= EXTI_IMR_MR13;

    /*Interrupt Software*/
    EXTI->SWIER &= ~EXTI_SWIER_SWIER13;

    /*Interrupt Pending Register*/
    EXTI->PR |= EXTI_PR_PR13;

    NVIC_EnableIRQ(EXTI15_10_IRQn);
}

void EXTI15_10_IRQHandler(void)
{
    if (EXTI->PR & EXTI_PR_PR13)
    {
        /* Clear the interrupt pending bit for EXTI line 13 */
        EXTI->PR |= EXTI_PR_PR13;
        exti13_flag = 1;

    }

}
